from collections import deque

def find_connected_components(grid):
    """Find all connected components of non-zero colors"""
    height, width = len(grid), len(grid[0])
    visited = set()
    components = []

    def get_component(start_r, start_c, color):
        comp = []
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))

        while queue:
            r, c = queue.popleft()
            comp.append((r, c))

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) not in visited and 0 <= nr < height and 0 <= nc < width:
                    if grid[nr][nc] == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return comp

    colored_cells = {}
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 and (r,c) not in visited:
                color = grid[r][c]
                colored_cells.setdefault(color, []).append((r, c))
                comp = get_component(r, c, color)
                visited.update(comp)

    return colored_cells, visited

def analyze_transform(input_grid, output_grid):
    """Analyze how connected components transform"""
