def find_components_by_color(grid):
    """Find all connected component regions for each color"""
    height, width = len(grid), len(grid[0])

    colors_in_grid = set()
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0:
                colors_in_grid.add(grid[r][c])

    components = {c: [] for c in colors_in_grid}

    visited = [[False]*width for _ in range(height)]

    def dfs(r, c, color, comp_list):
        stack = [(r, c)]
        visited[r][c] = True
        comp_list.append((r, c))

        while stack:
            curr_r, curr_c = stack.pop()

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < height and 0 <= nc < width:
                    if not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        comp_list.append((nr, nc))
                        stack.append((nr, nc))

    color_counter = {c: 0 for c in colors_in_grid}

    for r in range(height):
        for c in range(width):
            if not visited[r][c] and grid[r][c] != 0:
                color = grid[r][c]
                color_counter[color] += 1
                comp = []
                dfs(r, c, color, comp)
                components[color].append({
